using Dapper; using Sigov.Application.Agro.ComprasAgriculturaFamiliar; using Sigov.Application.Common; using Sigov.Infrastructure.Persistence.Dapper;
namespace Sigov.Infrastructure.Agro.Repositories;
public sealed class AgroCompraAgriculturaFamiliarRepository:IAgroCompraAgriculturaFamiliarRepository{private readonly DapperContext _c; public AgroCompraAgriculturaFamiliarRepository(DapperContext c)=>_c=c; public async Task<PagedResult<AgroCompraAgriculturaFamiliarResponse>> ListarAsync(long t,long e,long? ex,int p,int ps,CancellationToken ct){using var cn=_c.CreateConnection(); var rows=await cn.QueryAsync<AgroCompraAgriculturaFamiliarResponse>(new CommandDefinition("select id,tenant_id TenantId,entidade_id EntidadeId,exercicio_id ExercicioId,produtor_id ProdutorId,produto,quantidade,unidade_medida UnidadeMedida,valor_unitario ValorUnitario,valor_total ValorTotal,data_compra DataCompra,status,ativo from sigov.agro_compra_agricultura_familiar where tenant_id=@t and entidade_id=@e and is_deleted=false and (@ex is null or exercicio_id=@ex) order by data_compra desc,id desc limit @ps offset @o",new{t,e,ex,ps,o=(p-1)*ps},cancellationToken:ct)); return new(rows.AsList(),p,ps,rows.Count());} public async Task<AgroCompraAgriculturaFamiliarResponse?> ObterAsync(long t,long e,long id,CancellationToken ct){using var cn=_c.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<AgroCompraAgriculturaFamiliarResponse>(new CommandDefinition("select id,tenant_id TenantId,entidade_id EntidadeId,exercicio_id ExercicioId,produtor_id ProdutorId,produto,quantidade,unidade_medida UnidadeMedida,valor_unitario ValorUnitario,valor_total ValorTotal,data_compra DataCompra,status,ativo from sigov.agro_compra_agricultura_familiar where tenant_id=@t and entidade_id=@e and id=@id and is_deleted=false",new{t,e,id},cancellationToken:ct));} public async Task<long> CriarAsync(long t,long e,long? ex,long? u,AgroCompraAgriculturaFamiliarCreateRequest r,decimal vt,CancellationToken ct){using var cn=_c.CreateConnection(); return await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.agro_compra_agricultura_familiar(tenant_id,entidade_id,exercicio_id,produtor_id,programa_origem,processo_compra_id,contrato_id,escola_id,produto,quantidade,unidade_medida,valor_unitario,valor_total,data_compra,status,observacao,created_by) values(@t,@e,@ex,@ProdutorId,@ProgramaOrigem,@ProcessoCompraId,@ContratoId,@EscolaId,@Produto,@Quantidade,@UnidadeMedida,@ValorUnitario,@vt,@DataCompra,@Status,@Observacao,@u) returning id",new{t,e,ex,u,vt,r.ProdutorId,r.ProgramaOrigem,r.ProcessoCompraId,r.ContratoId,r.EscolaId,r.Produto,r.Quantidade,r.UnidadeMedida,r.ValorUnitario,r.DataCompra,r.Status,r.Observacao},cancellationToken:ct));} public async Task AtualizarAsync(long t,long e,long id,long? ex,long? u,AgroCompraAgriculturaFamiliarCreateRequest r,decimal vt,CancellationToken ct){using var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_compra_agricultura_familiar set produto=@Produto,quantidade=@Quantidade,unidade_medida=@UnidadeMedida,valor_unitario=@ValorUnitario,valor_total=@vt,status=@Status,updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and id=@id and (@ex is null or exercicio_id=@ex)",new{t,e,id,ex,u,vt,r.Produto,r.Quantidade,r.UnidadeMedida,r.ValorUnitario,r.Status},cancellationToken:ct));} public async Task CancelarAsync(long t,long e,long id,long? u,CancellationToken ct){using var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_compra_agricultura_familiar set status='CANCELADA',updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and id=@id",new{t,e,id,u},cancellationToken:ct));}}
